<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue'
import{ElMessage,ElMessageBox}from'element-plus'
import{useAuthStore}from'../../stores/auth'
import{getRecords}from'../../services/records'
import{cancelPrescription,createPrescription,getMedicines,getPrescriptions}from'../../services/prescriptions'
import type{MedicalRecord,Medicine,Prescription,PrescriptionItem}from'../../types/medical'

const auth=useAuthStore(),isDoctor=computed(()=>auth.user?.role==='doctor'),rows=ref<Prescription[]>([]),total=ref(0),loading=ref(false),dialog=ref(false),saving=ref(false),records=ref<MedicalRecord[]>([]),medicines=ref<Medicine[]>([])
const form=reactive<{record_id:number;notes:string;items:PrescriptionItem[]}>({record_id:0,notes:'',items:[]})
const statusLabel={issued:'待缴费取药',dispensed:'已取药',cancelled:'已作废'}
async function load(){loading.value=true;try{const data=await getPrescriptions();rows.value=data.results;total.value=data.count}catch{rows.value=[];total.value=0}finally{loading.value=false}}
async function openCreate(){Object.assign(form,{record_id:0,notes:'',items:[{medicine_id:0,dosage:'',frequency:'',duration:'',quantity:1}]});dialog.value=true;try{const[result,drugList]=await Promise.all([getRecords({status:'confirmed',can_prescribe:true}),getMedicines()]);records.value=result.results;medicines.value=drugList}catch{ElMessage.error('处方基础数据加载失败')}}
function addItem(){form.items.push({medicine_id:0,dosage:'',frequency:'',duration:'',quantity:1})}
function removeItem(index:number){if(form.items.length>1)form.items.splice(index,1)}
async function submit(){if(!form.record_id){ElMessage.warning('请选择已确认病历');return}if(form.items.some(item=>!item.medicine_id||!item.dosage.trim()||!item.frequency.trim()||item.quantity<1)){ElMessage.warning('请完整填写每条药品用法');return}saving.value=true;try{await createPrescription({record_id:form.record_id,notes:form.notes,items:form.items});ElMessage.success('处方已开具');dialog.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'处方开具失败')}finally{saving.value=false}}
async function cancel(row:Prescription){try{await ElMessageBox.confirm('作废后患者将看到处方已失效，且不能恢复。','作废处方',{type:'warning'});await cancelPrescription(row.id);ElMessage.success('处方已作废');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'操作失败')}}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">ELECTRONIC PRESCRIPTION</p><h1>{{isDoctor?'电子处方':'我的处方'}}</h1><p>{{isDoctor?'开具处方后自动生成药品账单，患者支付后自动发药':'支付药品账单后，系统将完成取药并更新处方状态'}}</p></div><el-button v-if="isDoctor" type="primary" @click="openCreate">＋ 开具处方</el-button><router-link v-else to="/patient/billing"><el-button type="primary">前往支付</el-button></router-link></div><el-card class="table-card"><el-table v-loading="loading" :data="rows" empty-text="暂无处方记录"><el-table-column prop="prescription_no" label="处方编号" min-width="145"/><el-table-column v-if="isDoctor" prop="patient_name" label="患者" min-width="110"/><el-table-column v-else prop="doctor_name" label="医师" min-width="110"/><el-table-column prop="diagnosis" label="临床诊断" min-width="160" show-overflow-tooltip/><el-table-column label="药品明细" min-width="250"><template #default="{row}"><div class="medicine-summary"><span v-for="item in row.items" :key="item.id||item.medicine_id">{{item.medicine_name}} × {{item.quantity}} · {{item.dosage}} {{item.frequency}}</span></div></template></el-table-column><el-table-column label="金额" width="105"><template #default="{row}">¥{{row.total_amount}}</template></el-table-column><el-table-column prop="bill_no" label="账单号" min-width="145"/><el-table-column label="状态" width="115"><template #default="{row}"><el-tag :type="row.status==='dispensed'?'success':row.status==='cancelled'?'info':'warning'">{{statusLabel[row.status as keyof typeof statusLabel]}}</el-tag></template></el-table-column><el-table-column v-if="isDoctor" label="操作" width="100"><template #default="{row}"><el-button v-if="row.status==='issued'" link type="danger" @click="cancel(row)">作废</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span></div></el-card><el-dialog v-model="dialog" title="开具电子处方" width="min(850px,96vw)" destroy-on-close><el-form label-position="top"><el-form-item label="关联病历" required><el-select v-model="form.record_id" filterable style="width:100%" placeholder="选择已确认的患者病历"><el-option v-for="record in records" :key="record.id" :label="`${record.patient_name} · ${record.record_no} · ${record.diagnosis}`" :value="record.id"/></el-select></el-form-item><div class="prescription-items"><div v-for="(item,index) in form.items" :key="index" class="prescription-row"><el-select v-model="item.medicine_id" filterable placeholder="选择药品"><el-option v-for="medicine in medicines" :key="medicine.id" :label="`${medicine.name} ${medicine.specification} · ¥${medicine.price} · 库存${medicine.stock}`" :value="medicine.id" :disabled="medicine.stock<=0"/></el-select><el-input v-model="item.dosage" placeholder="单次剂量"/><el-input v-model="item.frequency" placeholder="频次，如每日3次"/><el-input v-model="item.duration" placeholder="疗程，如7天"/><el-input-number v-model="item.quantity" :min="1" :max="999"/><el-button text type="danger" @click="removeItem(index)">删除</el-button></div></div><el-button class="add-line" @click="addItem">＋ 添加药品</el-button><el-form-item label="医嘱与备注"><el-input v-model="form.notes" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">确认开具并生成账单</el-button></template></el-dialog></section></template>
